!function(){"use strict";document.addEventListener("DOMContentLoaded",()=>{!function(){const e=document.getElementById("nk-section-nav"),n=document.querySelectorAll(".nk-nav-link");if(!e)return;const i=Array.from(n).map(e=>{const n=e.getAttribute("href").replace("#","");return{link:e,section:document.getElementById(n)}}).filter(e=>e.section),t=e=>{n.forEach(e=>e.classList.remove("active")),e.classList.add("active")};n.forEach(e=>{e.addEventListener("click",()=>t(e))});const r=new IntersectionObserver(n=>{n.forEach(n=>{if(n.isIntersecting){const i=n.target.id,r=e.querySelector(`[href="#${i}"]`);r&&t(r)}})},{rootMargin:"-40% 0px -50% 0px"});i.forEach(e=>r.observe(e.section))}(),function(){const e=document.querySelectorAll(".reveal");if(!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("visible"));const n=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),n.unobserve(e.target))})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});e.forEach(e=>n.observe(e))}(),window.Journey&&window.Journey.registerSearchItems("frontend/neelakurinji-explorer/index.html",[{id:"neelakurinji-main",title:"Neelakurinji Explorer",description:"Explore Neelakurinji (Strobilanthes kunthiana) — the famous flowering shrub endemic to the Western Ghats that blooms once every twelve years, painting hillsides in violet-blue.",link:"frontend/neelakurinji-explorer/index.html"},{id:"neelakurinji-flowering",title:"Neelakurinji 12-Year Flowering Cycle",description:"The plietesial flowering cycle of Neelakurinji — from 1838 through the 2018 mass bloom to the next expected flowering in 2030.",link:"frontend/neelakurinji-explorer/index.html#flowering"},{id:"neelakurinji-ecology",title:"Neelakurinji Ecological Importance",description:"How Neelakurinji supports pollinators, stabilises soil, provides wildlife food, and acts as a cultural keystone species in the Western Ghats.",link:"frontend/neelakurinji-explorer/index.html#ecology"}])})}();